  async function invite(event:FormEvent<HTMLFormElement>){
    event.preventDefault();
    const recipients=inviteCandidates.filter((person)=>inviteSelected.includes(person.id));
    if(!recipients.length){setError('Selecione pelo menos uma pessoa para convidar.');return;}
    setSaving(true);setError('');setNotice('');
    try{
      const inviteLink=await api<{id:string;token:string}>(`/api/messages-v2/servers/${serverId}/invites`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({expiresInDays:7})});
      setInviteOpen(false);setInviteSelected([]);setInviteSearch('');
      setNotice(`Enviando convites para ${recipients.length} ${recipients.length===1?'pessoa':'pessoas'}…`);
      let sent=0;let failed=0;
      // Create DMs as a batch, then send messages as a second batch. This avoids
      // making each recipient wait for their own create-then-send request chain.
      for(let offset=0;offset<recipients.length;offset+=50){
        const batch=recipients.slice(offset,offset+50);
        const conversations=await Promise.allSettled(batch.map(async(person)=>({person,direct:await api<{id:string}>('/api/messages-v2/direct',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({profileId:person.id})})})));
        const ready=conversations.flatMap((result)=>result.status==='fulfilled'?[result.value]:[]);
        failed+=batch.length-ready.length;
        const sends=await Promise.allSettled(ready.map(({direct})=>api(`/api/messages-v2/conversations/${direct.id}/messages`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({serverInvite:{serverId,inviteId:inviteLink.id,token:inviteLink.token}})})));
        sent+=sends.filter((result)=>result.status==='fulfilled').length;
        failed+=sends.length-sends.filter((result)=>result.status==='fulfilled').length;
        setNotice(`Enviando convites… ${sent+failed} de ${recipients.length}`);
      }
      if(!sent)throw new Error('Não foi possível enviar as mensagens privadas. Verifique se os destinatários aceitam mensagens.');
      setNotice(`${sent} ${sent===1?'convite enviado':'convites enviados'} por mensagem privada${failed?`; ${failed} não puderam ser enviados`:''}.`);
    }catch(reason){setError(reason instanceof Error?reason.message:'Não foi possível enviar os convites.');}
    finally{setSaving(false);}
  }
  async function send(event:FormEvent<HTMLFormElement>){event.preventDefault();if(!activeChannel||activeChannel.kind==='voice'||activeChannel.kind==='posts'||(!draft.trim()&&!messageFiles.length))return;const content=draft.trim();setDraft('');try{const attachments=await filesPayload(messageFiles);const created=await api<ServerMessage>(`/api/messages-v2/servers/${serverId}/channels/${activeChannel.id}/messages`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({content,attachments})});setMessages((items)=>[...items,created]);setMessageFiles([]);if(messageFileRef.current)messageFileRef.current.value='';}catch(reason){setDraft(content);setError(reason instanceof Error?reason.message:'Não foi possível enviar a mensagem.');}}
